export function installEnhancements(api){
 const $=s=>document.querySelector(s),esc=api.escapeHTML,fmt=api.formatIDR;
 const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 let month=today().slice(0,7),day=today(),events=[],owner=null,agendaBusy=false,chatBusy=false;
 const css=document.createElement('style');css.textContent=`.feature-toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:14px 0}.feature-toolbar input,.feature-toolbar select{max-width:100%;min-width:0;padding:9px}.calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px}.calendar-day{min-height:86px;min-width:0;border:1px solid var(--border);border-radius:10px;background:var(--bg);padding:9px;text-align:left;color:var(--text);cursor:pointer}.calendar-day.selected{outline:2px solid var(--primary);background:var(--primary-light)}.calendar-day small{display:block;font-size:10px;line-height:1.5}.calendar-weekday{text-align:center;font-size:11px;color:var(--text-muted);padding:7px}.calendar-list-item{padding:13px 0;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;gap:8px}.calendar-list-item>div{min-width:0;overflow-wrap:anywhere}.calendar-list-item button{white-space:nowrap;flex-shrink:0;padding:8px 10px}.calendar-actions{display:flex;gap:5px;flex-shrink:0}.calendar-list-item small{display:block;color:var(--text-muted);margin-top:4px}.ai-messages{display:flex;flex-direction:column;gap:12px;max-height:570px;overflow:auto;padding:8px 0}.ai-message{white-space:pre-wrap;overflow-wrap:anywhere;padding:14px;border-radius:14px;background:var(--bg);line-height:1.65;font-size:13px}.ai-message.user{align-self:flex-end;background:var(--primary-light);max-width:90%}.ai-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:12px 0}.ai-metrics>div{border:1px solid var(--border);padding:10px;border-radius:10px;font-size:12px}.ai-metrics b{display:block;font-size:16px;margin-top:4px}.ai-chat-form{display:flex;gap:8px;margin-top:14px}.ai-chat-form input{flex:1;min-width:0}.feature-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.ai-table{width:100%;border-collapse:collapse;font-size:12px}.ai-table td,.ai-table th{padding:7px;border-bottom:1px solid var(--border);text-align:left;overflow-wrap:anywhere}.ai-details{margin-top:12px;white-space:normal}.feature-shortcuts{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 16px}.ai-explain{padding:12px;background:var(--primary-light);border-radius:10px;white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:768px){.calendar-day{min-height:66px;padding:5px;border-radius:7px}.calendar-day small{font-size:9px}.calendar-grid{gap:3px}.ai-chat-form{flex-wrap:wrap}.ai-chat-form input{width:100%;flex-basis:100%}.ai-message{padding:11px}.feature-toolbar label{width:100%}.ai-metrics b{font-size:14px}}`;
 document.head.append(css);
 $('#viewCalendar').innerHTML=`<div class="card"><div class="card-head-title">📅 Kalender Terpadu</div><p class="report-explainer">Transaksi, jatuh tempo utang/piutang, dan agenda pribadi dalam satu kalender.</p><div class="feature-toolbar"><button class="secondary" id="calPrev" aria-label="Bulan sebelumnya">‹</button><input type="month" id="calendarMonth" value="${month}" aria-label="Bulan kalender"><button class="secondary" id="calNext" aria-label="Bulan berikutnya">›</button><button class="secondary" id="calToday">Hari ini</button><button class="primary" id="calAdd">+ Agenda</button></div><label style="font-size:12px"><input type="checkbox" id="calShowTx" checked> Tampilkan transaksi</label><p id="calendarNotice" role="status"></p><div class="calendar-grid" id="calendarGrid" style="margin-top:12px"></div></div><div class="card" style="margin-top:16px"><div class="card-head-title" id="calendarDayTitle"></div><div id="calendarDayList"></div></div>`;
 $('#viewAssistant').innerHTML=`<div class="card"><div class="card-head-title">✨ Asisten Keuangan</div><p class="report-explainer">Tanya pembukuan atau catat lewat chat. Periksa formulir sebelum menyimpan.</p><div class="feature-tabs"><button class="secondary ai-prompt" data-prompt="cek saldo">👛 Saldo</button><button class="secondary ai-prompt" data-prompt="cek piutang">🤝 Piutang</button><button class="secondary ai-prompt" data-prompt="rekap hari ini">📊 Rekap hari ini</button></div><div class="ai-messages" id="aiMessages" aria-live="polite"></div><form class="ai-chat-form" id="aiChatForm"><input id="aiChatInput" required maxlength="1200" placeholder="Contoh: Nuno bayar sejuta Tunai" autocomplete="off" aria-label="Pesan untuk asisten"><button class="primary" id="aiSend">Kirim</button></form><p id="aiNotice" role="status" style="font-size:12px;margin-top:8px"></p></div><div class="card" style="margin-top:16px"><div class="card-head-title">📊 Rekap & Ringkasan AI</div><form id="aiRecapForm" class="feature-toolbar"><select id="aiPeriod" aria-label="Periode rekap"><option value="daily">Harian</option><option value="weekly">Mingguan</option><option value="monthly" selected>Bulanan</option><option value="yearly">Tahunan</option><option value="custom">Rentang tanggal</option></select><input type="date" required id="aiAnchor" value="${today()}" aria-label="Tanggal acuan"><span id="aiCustomRange" hidden><input type="date" id="aiFrom" value="${today()}" aria-label="Dari tanggal"><input type="date" id="aiTo" value="${today()}" aria-label="Sampai tanggal"></span><button class="primary" id="aiRecapSubmit">Buat Rekap</button></form><div id="aiRecapResult" aria-live="polite"></div></div>`;
 function data(){return api.data();}
 function entries(date){const d=data();const tx=$('#calShowTx').checked?d.transactions.filter(t=>todayFrom(t.occurred_at)===date):[];const obs=d.obligations.filter(o=>o.due_date===date&&remaining(o)>0);return {tx,obs,agenda:events.filter(e=>e.event_date===date)};}
 function todayFrom(s){return s?new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(s)):'';}
 function remaining(o){return Math.max(0,Number(o.principal)-(o.obligation_payments||[]).reduce((a,p)=>a+Number(p.amount),0));}
 function renderCalendar(){
  const [y,m]=month.split('-').map(Number),first=new Date(Date.UTC(y,m-1,1)),count=new Date(Date.UTC(y,m,0)).getUTCDate(),offset=(first.getUTCDay()+6)%7;let html=['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(x=>`<div class="calendar-weekday">${x}</div>`).join('')+'<div></div>'.repeat(offset);
  for(let n=1;n<=count;n++){const date=month+'-'+String(n).padStart(2,'0'),e=entries(date);html+=`<button class="calendar-day ${date===day?'selected':''}" data-day="${date}" aria-label="${date}"><b>${n}${date===today()?' •':''}</b>${e.tx.length?`<small>🧾 ${e.tx.length}</small>`:''}${e.obs.length?`<small>🤝 ${e.obs.length}</small>`:''}${e.agenda.length?`<small>📌 ${e.agenda.length}</small>`:''}</button>`;}
  $('#calendarGrid').innerHTML=html;$('#calendarMonth').value=month;$('#calendarGrid').querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{day=b.dataset.day;renderCalendar()});
  $('#calendarDayTitle').textContent='Agenda · '+new Intl.DateTimeFormat('id-ID',{dateStyle:'long',timeZone:'UTC'}).format(new Date(day+'T00:00:00Z'));const e=entries(day),d=data();
  $('#calendarDayList').innerHTML=e.obs.map(o=>`<div class="calendar-list-item"><div>🤝 ${o.type==='debt'?'Utang kepada':'Piutang dari'} ${esc(o.contact_name)}<small>Jatuh tempo · Sisa ${fmt(remaining(o))}</small></div><button class="secondary" data-pay="${esc(o.id)}">${o.type==='debt'?'Bayar':'Terima'}</button></div>`).join('')+e.agenda.map(a=>`<div class="calendar-list-item"><div>${a.completed?'✅':'📌'} ${esc(a.title)}<small>${esc(a.note||'')}</small></div><div class="calendar-actions"><button class="secondary" data-done="${a.id}">${a.completed?'Buka':'Selesai'}</button><button class="danger" data-delete="${a.id}" aria-label="Hapus agenda">×</button></div></div>`).join('')+e.tx.map(t=>`<div class="calendar-list-item"><div>🧾 ${esc(t.description||'Transaksi')}<small>${esc(d.wallets.find(w=>w.id===t.wallet_id)?.name||'Dompet')} · ${esc(t.recorder_name||'Pemilik akun')}</small></div><b>${fmt(t.amount)}</b></div>`).join('')||'<p class="report-explainer">Belum ada agenda atau transaksi pada tanggal ini.</p>';
  $('#calendarDayList').querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>{const o=d.obligations.find(o=>o.id===b.dataset.pay);api.openPay(o.id,o.type,remaining(o));});
  $('#calendarDayList').querySelectorAll('[data-done]').forEach(b=>b.onclick=async()=>{const a=events.find(a=>a.id===b.dataset.done);await mutate(b,()=>api.db.from('calendar_events').update({completed:!a.completed}).eq('id',a.id).eq('owner_id',api.user().id));});
  $('#calendarDayList').querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Hapus agenda ini?'))await mutate(b,()=>api.db.from('calendar_events').delete().eq('id',b.dataset.delete).eq('owner_id',api.user().id));});
 }
 async function mutate(btn,fn){btn.disabled=true;try{const result=await fn();if(result.error)throw result.error;await refresh();}catch(e){$('#calendarNotice').textContent='Agenda belum tersimpan: '+e.message;}finally{btn.disabled=false;}}
 async function refresh(){const user=api.user();if(!user)return;if(owner!==user.id){owner=user.id;events=[];$('#aiMessages').replaceChildren();$('#aiRecapResult').replaceChildren();}renderCalendar();renderInstallments();renderReceiptWallets();if(agendaBusy)return;agendaBusy=true;const uid=user.id;try{const rows=[];for(let offset=0;;offset+=1000){const result=await api.db.from('calendar_events').select('*').eq('owner_id',uid).order('event_date').order('id').range(offset,offset+999);if(result.error)throw result.error;rows.push(...result.data);if(result.data.length<1000)break;}if(api.user()?.id!==uid)return;events=rows;$('#calendarNotice').textContent='';renderCalendar();}catch(e){if(api.user()?.id===uid)$('#calendarNotice').textContent='Agenda belum dapat dimuat: '+e.message;}finally{agendaBusy=false;}}
 function move(n){const [y,m]=month.split('-').map(Number);month=new Date(Date.UTC(y,m-1+n,1)).toISOString().slice(0,7);day=month+'-01';renderCalendar();}
 $('#calPrev').onclick=()=>move(-1);$('#calNext').onclick=()=>move(1);$('#calendarMonth').onchange=e=>{if(!/^\d{4}-\d{2}$/.test(e.target.value))return;month=e.target.value;day=month+'-01';renderCalendar();};$('#calToday').onclick=()=>{month=today().slice(0,7);day=today();renderCalendar();};$('#calShowTx').onchange=renderCalendar;
 $('#calAdd').onclick=()=>api.showModal('📌 Tambah Agenda',`<label>Judul<input required name="title" maxlength="120" style="width:100%"></label><label>Tanggal<input required type="date" name="event_date" value="${day}" style="width:100%"></label><label>Catatan<textarea name="note" maxlength="500" style="width:100%"></textarea></label><p class="report-explainer">Agenda muncul pada kalender; tidak mengubah saldo.</p><button class="primary">Simpan Agenda</button>`,async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target)),result=await api.db.from('calendar_events').insert({owner_id:api.user().id,title:v.title.trim(),event_date:v.event_date,note:v.note.trim()});if(result.error){alert('Gagal menyimpan agenda: '+result.error.message);return;}api.closeModal();day=v.event_date;month=day.slice(0,7);await refresh();});
 async function request(body){const uid=api.user()?.id;if(!uid)throw Error('Silakan login');const {data,error}=await api.db.auth.getSession();if(error||!data.session)throw Error('Sesi berakhir. Silakan login lagi.');const response=await fetch(api.url+'/functions/v1/telegram-webhook/assistant',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+data.session.access_token},body:JSON.stringify(body),signal:AbortSignal.timeout(30000)});const result=await response.json();if(api.user()?.id!==uid)throw Error('Akun berubah. Kirim ulang dari akun saat ini.');if(!response.ok)throw Error(result.error||'Asisten belum tersedia');return result;}
 function message(text,role='assistant'){const el=document.createElement('div');el.className='ai-message '+role;el.textContent=text;$('#aiMessages').append(el);el.scrollIntoView({block:'nearest'});return el;}
 function review(p){
  if(p.intent==='obligation'){api.openObligation(p.obligation_type);fill({contact_name:p.contact_name,principal:p.amount,wallet_id:p.wallet_id,due_date:p.due_date||''});}
  else if(p.intent==='payment'){const o=data().obligations.find(o=>o.id===p.obligation_id);if(!o){alert('Tagihan berubah. Muat ulang pembukuan.');return;}api.openPay(o.id,o.type,remaining(o));fill({amount:p.amount,wallet_id:p.wallet_id});}
  else {api.openTransaction();$('#txKindSelect').value=p.kind;$('#txKindSelect').dispatchEvent(new Event('change'));fill({amount:p.amount,wallet_id:p.wallet_id,destination_wallet_id:p.destination_wallet_id||'',category_id:p.category_id||'',description:p.description,...(p.receipt_date?{occurred_at:p.receipt_date}:{})});}
 }
 function fill(values){for(const [k,v]of Object.entries(values)){const el=$('#modalForm').querySelector(`[name="${k}"]`);if(el)el.value=v;}}
 function displayRecap(result,target){const r=result.recap;target.innerHTML=`<p class="report-explainer">${esc(r.start)} — ${esc(r.end)} · Dibandingkan ${esc(r.previousStart)} — ${esc(r.previousEnd)}</p><div class="ai-explain"></div><div class="ai-metrics">${[['Pendapatan',r.income],['Pengeluaran',r.expense],['Arus kas masuk',r.cashIn],['Arus kas keluar',r.cashOut],['Arus kas bersih',r.net],['Saldo akhir periode',r.closing],['Sisa utang',r.pendingDebt],['Sisa piutang',r.pendingReceivable]].map(([label,n])=>`<div>${label}<b>${fmt(n)}</b></div>`).join('')}</div><p class="report-explainer">Perubahan pendapatan: ${fmt(r.income-r.previous.income)} · Perubahan pengeluaran: ${fmt(r.expense-r.previous.expense)}. Saldo awal: ${fmt(r.opening)}. Transaksi: ${r.count}.</p><p class="report-explainer">Utang diterima ${fmt(r.debtReceived)} · Utang dibayar ${fmt(r.debtPaid)} · Piutang diberikan ${fmt(r.receivableGiven)} · Piutang dibayar ${fmt(r.receivablePaid)}. Transfer antar-dompet tidak dihitung sebagai pendapatan/pengeluaran.</p><details class="ai-details"><summary>Dompet, kategori & pencatat</summary>${table('Dompet',r.wallets.map(w=>[w.name,fmt(w.opening)+' → '+fmt(w.closing)]))}${table('Kategori pengeluaran terbesar',r.categories.map(c=>[c.name,fmt(c.amount)]))}${table('Nilai transaksi per pencatat (termasuk transfer)',r.recorders.map(c=>[c.name,fmt(c.amount)]))}</details><p class="report-explainer">${result.ai?'✨ Penjelasan dibantu Gemini.':'Ringkasan otomatis ditampilkan; Gemini sedang tidak tersedia atau kuotanya habis.'} Angka dihitung dari database.</p>`;target.querySelector('.ai-explain').textContent=result.explanation||'';}
 function table(title,rows){return `<h4 style="margin:12px 0">${title}</h4><table class="ai-table"><tbody>${rows.length?rows.map(([a,b])=>`<tr><td>${esc(a)}</td><td>${esc(b)}</td></tr>`).join(''):'<tr><td>Belum ada data</td></tr>'}</tbody></table>`;}
 async function chat(text){if(chatBusy)return;chatBusy=true;$('#aiSend').disabled=true;$('#aiNotice').textContent='Memproses…';message(text,'user');try{const result=await request({action:'chat',text});const el=message(result.text||'');if(result.type==='draft'){const b=document.createElement('button');b.className='primary';b.textContent='🔎 Periksa & Simpan';b.style.marginTop='10px';b.onclick=()=>review(result.parsed);el.append(document.createElement('br'),b);}if(result.type==='clarification')for(const suggestion of (result.suggestions||[])){const b=document.createElement('button');b.className='secondary';b.textContent=suggestion;b.onclick=()=>{$('#aiChatInput').value=suggestion;$('#aiChatInput').focus();};el.append(document.createElement('br'),b);}if(result.type==='cancel_preview')cancelButton(el,result);if(result.type==='recap'){el.textContent='';displayRecap(result,el);}$('#aiNotice').textContent='';}catch(e){$('#aiNotice').textContent=e.message;}finally{chatBusy=false;$('#aiSend').disabled=false;}}
 $('#aiChatForm').onsubmit=e=>{e.preventDefault();const text=$('#aiChatInput').value.trim();if(!text)return;$('#aiChatInput').value='';chat(text);};document.querySelectorAll('.ai-prompt').forEach(b=>b.onclick=()=>chat(b.dataset.prompt));
 $('#aiPeriod').onchange=()=>{$('#aiCustomRange').hidden=$('#aiPeriod').value!=='custom';$('#aiAnchor').hidden=$('#aiPeriod').value==='custom';};
 $('#aiRecapForm').onsubmit=async e=>{e.preventDefault();$('#aiRecapSubmit').disabled=true;$('#aiRecapResult').textContent='Menghitung rekap…';try{const result=await request({action:'recap',period:$('#aiPeriod').value,anchor:$('#aiAnchor').value,from:$('#aiFrom').value,to:$('#aiTo').value});displayRecap(result,$('#aiRecapResult'));}catch(err){$('#aiRecapResult').textContent=err.message;}finally{$('#aiRecapSubmit').disabled=false;}};

 const receiptCard=document.createElement('div');receiptCard.className='card';receiptCard.style.marginTop='16px';receiptCard.id='receiptPanel';receiptCard.innerHTML=`<div class="card-head-title">📷 Foto Struk</div><p class="report-explainer">Foto atau unggah struk. AI mengisi transaksi otomatis, lalu Anda memeriksa dan menekan Simpan.</p><div class="feature-toolbar"><select id="receiptKind" aria-label="Jenis transaksi struk"><option value="expense">Pengeluaran</option><option value="income">Pemasukan</option></select><select id="receiptWallet" aria-label="Dompet struk"></select><button class="secondary" id="receiptCamera">📷 Ambil Foto</button><button class="secondary" id="receiptGallery">🖼 Unggah Foto</button><input hidden id="receiptCameraInput" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"><input hidden id="receiptGalleryInput" type="file" accept="image/jpeg,image/png,image/webp"></div><p id="receiptNotice" role="status"></p><img id="receiptImage" hidden alt="Foto struk yang dipilih" style="max-width:100%;max-height:300px;border-radius:10px"><div class="feature-toolbar"><button class="primary" id="receiptRead" disabled>✨ Baca & Isi Transaksi</button></div><div id="receiptResult"></div>`;$('#viewAssistant').prepend(receiptCard);
 let photo=null,photoOwner=null,receiptBusy=false;
 function clearPhoto(){photo=null;photoOwner=null;$('#receiptImage').hidden=true;$('#receiptImage').removeAttribute('src');$('#receiptRead').disabled=true;$('#receiptResult').replaceChildren();$('#receiptNotice').textContent='';}
 function renderReceiptWallets(){if(photoOwner&&photoOwner!==api.user()?.id)clearPhoto();const selected=$('#receiptWallet').value;$('#receiptWallet').innerHTML=data().wallets.filter(w=>w.is_active!==false).map(w=>`<option value="${esc(w.id)}">${esc(w.name)}</option>`).join('');if([...$('#receiptWallet').options].some(o=>o.value===selected))$('#receiptWallet').value=selected;}
 async function choosePhoto(file){if(receiptBusy||!file)return;clearPhoto();const uid=api.user()?.id;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12*1024*1024)throw Error('Gunakan JPG, PNG, atau WebP maksimal 12 MB.');const image=await createImageBitmap(file);const scale=Math.min(1,1800/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);image.close();const url=canvas.toDataURL('image/jpeg',0.82);if(url.length>3200000)throw Error('Foto terlalu besar. Foto ulang dengan ukuran lebih kecil.');if(api.user()?.id!==uid)return;photo=url.split(',')[1];photoOwner=uid;$('#receiptImage').src=url;$('#receiptImage').hidden=false;$('#receiptRead').disabled=false;$('#receiptNotice').textContent='Foto siap dibaca. Pastikan jenis transaksi dan dompet benar.';}catch(e){$('#receiptNotice').textContent=e.message;}}
 $('#receiptCamera').onclick=()=>$('#receiptCameraInput').click();$('#receiptGallery').onclick=()=>$('#receiptGalleryInput').click();for(const id of ['receiptCameraInput','receiptGalleryInput'])$('#'+id).onchange=e=>{choosePhoto(e.target.files[0]);e.target.value='';};
 $('#receiptRead').onclick=async()=>{if(receiptBusy||!photo||photoOwner!==api.user()?.id)return;receiptBusy=true;$('#receiptRead').disabled=true;$('#receiptNotice').textContent='Membaca struk…';try{const result=await request({action:'receipt',image:photo,mime_type:'image/jpeg',kind:$('#receiptKind').value,wallet_id:$('#receiptWallet').value});$('#receiptNotice').textContent=result.text;$('#receiptResult').replaceChildren();if(result.type==='receipt'){const r=result.receipt;$('#receiptResult').innerHTML=`<p><b>${esc(r.merchant)} · ${fmt(r.total)}</b></p><p class="report-explainer">${r.date?esc(r.date):'Tanggal belum terbaca. Formulir memakai hari ini; ubah bila berbeda.'} ${esc(r.notes||'')}</p>${table('Isi struk',r.items.map(i=>[i.name,fmt(i.total)]))}<button class="primary" id="receiptReview">🔎 Periksa & Simpan</button>`;$('#receiptReview').onclick=()=>review(result.parsed);review(result.parsed);}}catch(e){$('#receiptNotice').textContent=e.message;}finally{receiptBusy=false;$('#receiptRead').disabled=!photo;}};
 function cancelButton(el,result){const b=document.createElement('button');b.className='danger';b.textContent='🗑 Konfirmasi Pembatalan';b.onclick=async()=>{b.disabled=true;try{const r=await request({action:'cancel_confirm',transaction_id:result.transaction_id});message(r.text);if(r.changed)await api.reload();}catch(e){message(e.message);b.disabled=false;}};el.append(document.createElement('br'),b);}
 const installmentCard=document.createElement('div');installmentCard.className='card';installmentCard.style.marginTop='18px';installmentCard.innerHTML=`<div class="card-head-title">💳 Cicilan & Riwayat Pembayaran</div><p class="report-explainer">Bayar sebagian atau lunasi. Setiap cicilan memperbarui saldo dompet dan sisa tagihan.</p><div class="feature-toolbar"><select id="installmentFilter" aria-label="Filter cicilan"><option value="all">Semua tagihan</option><option value="receivable">Piutang</option><option value="debt">Utang</option></select></div><div id="installmentList"></div>`;$('#viewObligations').append(installmentCard);
 function renderInstallments(){const d=data(),filter=$('#installmentFilter').value;$('#installmentList').innerHTML=d.obligations.filter(o=>filter==='all'||o.type===filter).map(o=>{const paid=Number(o.principal)-remaining(o),payments=[...(o.obligation_payments||[])].sort((a,b)=>String(b.paid_at).localeCompare(String(a.paid_at)));return `<div style="padding:15px 0;border-bottom:1px solid var(--border);overflow-wrap:anywhere"><b>${o.type==='debt'?'📤 Utang kepada':'📥 Piutang dari'} ${esc(o.contact_name)}</b><p style="font-size:12px;margin:9px 0">Pokok ${fmt(o.principal)} · Dibayar ${fmt(paid)} · Sisa <b>${fmt(remaining(o))}</b></p><progress max="${Number(o.principal)}" value="${paid}" style="width:100%;accent-color:var(--primary)"></progress><div class="feature-toolbar">${remaining(o)>0?`<button class="primary" data-installment="${esc(o.id)}">+ Catat Cicilan / Pelunasan</button>`:'<span>✅ Lunas</span>'}</div><details><summary>${payments.length} pembayaran · Lihat riwayat</summary>${payments.length?payments.map(p=>`<div class="calendar-list-item"><div>${fmt(p.amount)}<small>${esc(todayFrom(p.paid_at))} · ${esc(d.wallets.find(w=>w.id===p.wallet_id)?.name||'Dompet')} · ${esc(p.recorder_name||'Pemilik akun')}<br>${esc(p.note||'')}</small></div>${p.transaction_id?`<button class="secondary" data-cancel-payment="${esc(p.transaction_id)}">Batalkan</button>`:''}</div>`).join(''):'<p class="report-explainer">Belum ada cicilan.</p>'}</details></div>`;}).join('')||'<p class="report-explainer">Catat utang atau piutang terlebih dahulu.</p>';$('#installmentList').querySelectorAll('[data-installment]').forEach(b=>b.onclick=()=>{const o=d.obligations.find(o=>o.id===b.dataset.installment);api.openPay(o.id,o.type,remaining(o));});$('#installmentList').querySelectorAll('[data-cancel-payment]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await request({action:'chat',text:'batal transaksi '+b.dataset.cancelPayment});if(r.type==='cancel_preview')api.showModal('Konfirmasi pembatalan cicilan',`<p style="white-space:pre-wrap">${esc(r.text)}</p><button class="danger">Ya, Batalkan Cicilan</button>`,async e=>{e.preventDefault();const submit=e.target.querySelector('button');submit.disabled=true;try{const result=await request({action:'cancel_confirm',transaction_id:r.transaction_id});if(result.changed){api.closeModal();await api.reload();}else{alert(result.text);submit.disabled=false;}}catch(err){alert(err.message);submit.disabled=false;}});else alert(r.text);}catch(e){alert(e.message);}finally{b.disabled=false;}});}
 $('#installmentFilter').onchange=renderInstallments;
 for(const view of ['viewHome','viewTx']){const b=document.createElement('button');b.className='secondary';b.textContent='📷 Foto Struk';b.style.marginBottom='12px';b.onclick=()=>{document.querySelector('[data-view="viewAssistant"]').click();$('#receiptPanel').scrollIntoView({block:'start'});};$('#'+view).prepend(b);}
 renderReceiptWallets();renderInstallments();renderCalendar();return {refresh};
}
